"use client";

import { CornerDownLeftIcon, Loader2Icon, SquareIcon, XIcon } from "lucide-react";
import type { KeyboardEvent } from "react";

import { InputGroup, InputGroupButton, InputGroupTextarea } from "@/components/ui/input-group";

type AgentStatus = "error" | "ready" | "resuming" | "streaming" | "submitted";

interface AgentComposerProps {
  disabled?: boolean;
  onChange: (value: string) => void;
  onStop: () => void;
  onSubmit: (text: string) => void;
  placeholder?: string;
  status: AgentStatus;
  value: string;
}

export function AgentComposer({
  disabled = false,
  onChange,
  onStop,
  onSubmit,
  placeholder,
  status,
  value,
}: AgentComposerProps) {
  const isBusy = status === "submitted" || status === "streaming";
  const submit = () => {
    if (disabled || status === "resuming") return;
    if (isBusy) {
      onStop();
      return;
    }
    const text = value.trim();
    if (!text) return;
    onSubmit(text);
  };
  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key !== "Enter" || e.shiftKey || e.nativeEvent.isComposing) return;
    e.preventDefault();
    submit();
  };
  let icon = <CornerDownLeftIcon className="size-4" />;
  if (status === "submitted") icon = <Loader2Icon className="size-4 animate-spin" />;
  else if (status === "streaming") icon = <SquareIcon className="size-4" />;
  else if (status === "error") icon = <XIcon className="size-4" />;
  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        submit();
      }}
      className="px-2.5 py-2.5"
    >
      <InputGroup className="h-auto flex-row items-end rounded-lg border-border bg-transparent shadow-none has-[[data-slot=input-group-control]:focus-visible]:border-foreground has-[[data-slot=input-group-control]:focus-visible]:ring-0">
        <InputGroupTextarea
          aria-label="Message Shop Agent"
          value={value}
          placeholder={placeholder}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          className="field-sizing-content max-h-48 min-h-11 py-2.5"
        />
        <InputGroupButton
          type="submit"
          size="icon-sm"
          variant="default"
          aria-label={isBusy ? "Stop" : "Send"}
          disabled={disabled || status === "resuming" || (!value.trim() && !isBusy)}
          className="mr-1.5 mb-1.5"
        >
          {icon}
        </InputGroupButton>
      </InputGroup>
    </form>
  );
}

import { defineMcpClientConnection } from "eve/connections";

export default defineMcpClientConnection({
  description:
    "Answer questions about this store's shipping, returns, payments, warranty, sizing, care, policies and FAQs. Do not invent answers when this source is unavailable.",
  tools: { allow: ["search_shop_policies_and_faqs"] },
  url: `https://${process.env.NEXT_PUBLIC_SHOPIFY_STORE_DOMAIN}/api/mcp`,
});

# Connect an existing Shopify store

Use the installed Shopify AI Toolkit and Shopify CLI. The template sends `X-Shopify-Storefront-Access-Token`, so it needs a public Storefront access token, not Shopify CLI's Admin token or a Headless private token.

## Authenticate

1. Normalize the supplied URL to `<handle>.myshopify.com`.
2. Check `shopify version`. If `shopify store auth` or `shopify store execute` is unavailable, upgrade Shopify CLI before continuing.
3. Validate the Admin GraphQL operation with the Shopify toolkit and use the exact required scopes it reports.
4. Authenticate with `shopify store auth --store <handle>.myshopify.com --scopes <required-scopes>`.

## Reuse or create a token

First query the shop ID, name, description, and existing public tokens with `shopify store execute --store <handle>.myshopify.com --query '...'`:

```graphql
query VercelShopStorefrontTokens {
  shop {
    description
    id
    name
    storefrontAccessTokens(first: 100) {
      nodes {
        accessToken
        title
      }
    }
  }
}
```

Prefer an existing token titled `Vercel Shop`. If none exists, validate and run this mutation with `shopify store execute`, including `--allow-mutations`:

```graphql
mutation VercelShopStorefrontTokenCreate($input: StorefrontAccessTokenInput!) {
  storefrontAccessTokenCreate(input: $input) {
    storefrontAccessToken {
      accessToken
      title
    }
    userErrors {
      field
      message
    }
  }
}
```

Pass `{ "input": { "title": "Vercel Shop" } }` through `--variables`.

Do not print the token in the final response. Write these values to `.env.local`:

- `NEXT_PUBLIC_SHOPIFY_SHOP_ID`: numeric part of `shop.id` (`gid://shopify/Shop/123456789` becomes `123456789`)
- `NEXT_PUBLIC_SHOPIFY_STORE_DOMAIN`: normalized `.myshopify.com` domain
- `NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN`: reused or created public token

The storefront display name and description are not environment variables. If `shop.name` differs from the default, set it as the `site.name` literal in `lib/config/index.ts`. If `shop.description` is set, use it as the `site.description` literal.

## Fallback

The authenticated connector might not be allowed to read or create Storefront tokens. If Shopify returns `ACCESS_DENIED`, reports that the app is not extendable, or lacks the required unauthenticated scopes:

1. Direct the user to **Shopify admin → Settings → Apps and sales channels → Headless**.
2. Ask them to create or select a storefront and copy its public Storefront API token directly into `.env.local` as `NEXT_PUBLIC_SHOPIFY_STOREFRONT_ACCESS_TOKEN`.
3. If `shop.id` was not read, ask them to set `NEXT_PUBLIC_SHOPIFY_SHOP_ID` to the number in the store's customer accounts URL, `https://shopify.com/<shop-id>/account`.
4. Never ask them to paste the token into chat.

"use server";

import { z } from "zod";

import { PRODUCTS_PER_PAGE, resolveBrowseParams } from "@/lib/collections";
import type { BrowseSource } from "@/lib/collections/types";
import type { ProductPage } from "@/lib/product/types";
import {
  fetchCollectionProducts,
  fetchSearchIndexProducts,
} from "@/lib/shopify/operations/products/server";

const LOAD_MORE_INPUT = z.strictObject({
  cursor: z.string().min(1),
  search: z.string(),
  source: z.discriminatedUnion("type", [
    z.strictObject({ collection: z.string().min(1), type: z.literal("collection") }),
    z.strictObject({ query: z.string().optional(), type: z.literal("search") }),
  ]) satisfies z.ZodType<BrowseSource>,
});

const EMPTY_PAGE: ProductPage = {
  pageInfo: { endCursor: null, hasNextPage: false, hasPreviousPage: false, startCursor: null },
  products: [],
};

export async function loadMoreBrowseProductsAction(input: {
  cursor: string;
  search: string;
  source: BrowseSource;
}): Promise<ProductPage> {
  const parsed = LOAD_MORE_INPUT.safeParse(input);
  if (!parsed.success) return EMPTY_PAGE;
  const { cursor, search, source } = parsed.data;

  const { filters, sort } = resolveBrowseParams(search);
  const page = { cursor, filters, limit: PRODUCTS_PER_PAGE, sortKey: sort };
  if (source.type === "search") {
    // Storefront `search` cursor is anchored to the original `first`; using a different page size returns count=0.
    return fetchSearchIndexProducts({ ...page, query: source.query });
  }
  const { pageInfo, products } = await fetchCollectionProducts({
    ...page,
    collection: source.collection,
  });
  return { pageInfo, products };
}

