import { formatPrice } from "@/lib/money";
import { fetchCustomerOrders } from "@/lib/shopify/operations/customer/server";

export default function OrdersPage({
  searchParams,
}: {
  searchParams: Promise<{ after?: string; before?: string }>;
}) {
  return (
    <>
      <AccountPageHeader title="Orders" description="View your order history" />
      <Suspense fallback={<OrdersSkeleton />}>
        <OrdersContent searchParams={searchParams} />
      </Suspense>
    </>
  );
}

async function OrdersContent({
  searchParams,
}: {
  searchParams: Promise<{ after?: string; before?: string }>;
}) {
  const params = await searchParams;
  const { orders, pageInfo } = await fetchCustomerOrders({
    after: params.after,
    before: params.before,
  });
  if (orders.length === 0) {
    return (
      <div className="rounded-lg border p-6 text-center">
        <p className="text-sm text-muted-foreground">You have no orders yet.</p>
      </div>
    );
  }
  return (
    <div className="grid gap-4">
      <ul className="grid gap-3">
        {orders.map((order) => (
          <li key={order.id}>
            <Link
              href={`/account/orders/${encodeURIComponent(order.id)}`}
              className="flex items-center justify-between gap-4 rounded-lg border p-4 transition-colors hover:bg-accent"
            >
              <div className="grid gap-1">
                <span className="font-medium">{order.name}</span>
                <span className="text-xs text-muted-foreground">
                  {formatOrderDate(order.processedAt)}
                </span>
              </div>
              <div className="flex items-center gap-3">
                <OrderStatusBadge status={order.fulfillmentStatus} />
                <span className="text-sm tabular-nums">{formatPrice(order.totalPrice)}</span>
              </div>
            </Link>
          </li>
        ))}
      </ul>

      {pageInfo.hasNextPage || pageInfo.hasPreviousPage ? (
        <div className="flex items-center justify-between">
          {pageInfo.hasPreviousPage && pageInfo.startCursor ? (
            <Button
              variant="outline"
              size="sm"
              render={
                <Link href={`/account/orders?before=${encodeURIComponent(pageInfo.startCursor)}`} />
              }
            >
              Newer
            </Button>
          ) : (
            <span />
          )}
          {pageInfo.hasNextPage && pageInfo.endCursor ? (
            <Button
              variant="outline"
              size="sm"
              render={
                <Link href={`/account/orders?after=${encodeURIComponent(pageInfo.endCursor)}`} />
              }
            >
              Older
            </Button>
          ) : (
            <span />
          )}
        </div>
      ) : null}
    </div>
  );
}

function OrdersSkeleton() {
  return (
    <div className="grid gap-3">
      {Array.from({ length: 4 }).map((_, index) => (
        <Skeleton key={index} className="h-18 w-full rounded-lg" />
      ))}
    </div>
  );
}
